import React from 'react';
import './Home.css';

function Home({ lang, text }) {
  return (
    <div className="home">
      <h1>
        {lang === 'ru'
          ? 'Добро пожаловать в нашу кофейню'
          : 'Welcome to our coffee shop'}
      </h1>

      <p className="slogan">
        {lang === 'ru'
          ? 'Лучший кофе в городе'
          : 'The best coffee in town'}
      </p>

      <div className="coffee-image">
        <img src="/coffee-cup.svg" alt="Чашка кофе" className="coffee-img" />
      </div>

      <p className="description">
        {lang === 'ru'
          ? 'Уютная атмосфера, свежая выпечка и авторские напитки'
          : 'Cozy atmosphere, fresh pastries and author\'s drinks'}
      </p>

      <p className="work-hours">
        🕒 {lang === 'ru' ? 'Работаем ежедневно с 8:00 до 22:00' : 'Open daily from 8:00 AM to 10:00 PM'}
      </p>

      <p className="motto">
        {lang === 'ru'
          ? '«Наш девиз: Кофе, который вдохновляет»'
          : '"Our motto: Coffee that inspires"'}
      </p>

      <button className="menu-button">
        {lang === 'ru' ? '🍽️ Смотреть меню' : '🍽️ View menu'}
      </button>
    </div>
  );
}

export default Home;
